\loigiai{
\begin{itemchoice}
\itemch Sai vì cạnh đối góc $\widehat{BAO}$ là $OB$, cạnh huyền $OA$ nên $\sin \widehat{BAO} = \dfrac{OB}{OA}$.
\itemch Sai vì $BD = OC = 1\,\text{m}$.
\itemch Trong $\triangle ABO$ vuông tại $B$, $AB = BO \cdot \tan \widehat{AOB} = BO \cdot \tan 58^{\circ}$.
\itemch $AD = AB + BD = 70\cdot\tan 58^{\circ} + 1 \approx 113\,\text{m}$.
\end{itemchoice}
